10	/// An unauthorized PLC operation detected by the monitor.
11	#[derive(Debug, Clone, Serialize)]
12	#[serde(rename_all = "camelCase")]
13	pub struct UnauthorizedChange {
14	    /// CID of the unauthorized operation.
15	    pub cid: String,
16	    /// ISO 8601 timestamp when plc.directory accepted the operation.
17	    /// Frontend computes recovery deadline from this timestamp.
18	    pub created_at: String,
19	    /// did:key URI of the key that signed this operation, if identified.
20	    /// None if the signing key could not be determined from known rotation keys.
21	    pub signing_key: Option<String>,
22	    /// The raw PLC operation JSON for display in alert detail.
23	    pub operation: serde_json::Value,
24	}
