26	/// Result of checking a single identity's PLC status.
27	#[derive(Debug, Clone, Serialize)]
28	#[serde(rename_all = "camelCase")]
29	pub struct IdentityStatus {
30	    pub did: String,
31	    /// True when the monitor could not reach plc.directory or parse the audit log.
32	    /// The frontend should show a degraded-monitoring indicator instead of "all clear."
33	    pub check_failed: bool,
34	    pub unauthorized_changes: Vec<UnauthorizedChange>,
35	}
