219	const MONITOR_INTERVAL_SECS: u64 = 15 * 60; // 15 minutes
220	
221	/// Run a single monitoring cycle. Extracted from the loop for testability.
222	/// Returns the list of identity statuses with any alerts.
223	pub async fn run_monitoring_cycle(monitor: &PlcMonitor<'_>) -> Vec<IdentityStatus> {
224	    match monitor.check_all().await {
225	        Ok(statuses) => statuses,
226	        Err(e) => {
227	            tracing::warn!(error = %e, "Monitoring cycle check_all failed");
228	            vec![]
229	        }
230	    }
231	}
232	
233	/// Run the PLC monitoring loop. Spawned once during app setup.
234	/// Checks all managed identities every MONITOR_INTERVAL_SECS and emits
235	/// "plc_alert" events to the frontend when unauthorized changes are detected.
236	pub async fn run_monitoring_loop(app_handle: tauri::AppHandle) {
237	    let mut interval = interval(Duration::from_secs(MONITOR_INTERVAL_SECS));
238	    // Don't burst-fire missed ticks after iOS suspension
239	    interval.set_missed_tick_behavior(MissedTickBehavior::Delay);
240	    // Skip the first immediate tick — let the app finish initializing
241	    interval.tick().await;
242	
243	    loop {
244	        interval.tick().await;
245	
246	        let state = app_handle.state::<crate::oauth::AppState>();
247	        let monitor = PlcMonitor::new(state.pds_client());
248	        let statuses = run_monitoring_cycle(&monitor).await;
249	
250	        emit_if_alerts(&app_handle, &statuses);
251	    }
252	    // If the loop ever exits (shouldn't happen), log it so we know monitoring died.
253	    // The `loop` above has no `break`, so control never falls through here — the
254	    // allow keeps this defensive epilogue compiling as intentional dead code.
255	    #[allow(unreachable_code)]
256	    {
257	        tracing::error!("PLC monitoring loop exited unexpectedly");
258	    }
259	}
260	
261	/// Emit "plc_alert" event to the frontend if any identity has unauthorized changes.
262	fn emit_if_alerts(app_handle: &tauri::AppHandle, statuses: &[IdentityStatus]) {
263	    let has_alerts = statuses.iter().any(|s| !s.unauthorized_changes.is_empty());
264	    if has_alerts {
265	        if let Err(e) = app_handle.emit("plc_alert", statuses) {
266	            tracing::warn!(error = %e, "failed to emit plc_alert event");
267	        }
268	    }
269	}
270	
271	/// Tauri IPC command: check all managed identities for unauthorized PLC operations.
272	/// Also emits "plc_alert" event so IdentityListHome's event listener receives updates.
273	#[tauri::command]
274	pub async fn check_identity_status(
275	    app: tauri::AppHandle,
276	    state: tauri::State<'_, crate::oauth::AppState>,
277	) -> Result<Vec<IdentityStatus>, MonitorError> {
278	    let monitor = PlcMonitor::new(state.pds_client());
279	    let statuses = monitor.check_all().await?;
280	    emit_if_alerts(&app, &statuses);
281	    Ok(statuses)
282	}
