442	        let monitor = PlcMonitor::new(&client);
443	
444	        // Use a separate rotation key (rotationKeys[0]); device key signs as rotationKeys[1]
445	        let other_kp = crypto::generate_p256_keypair().expect("keygen");
446	        let genesis_op = crypto::build_did_plc_genesis_op(
447	            &other_kp.key_id,
448	            &DidKeyUri(device_pub.key_id.clone()),
449	            &device_priv,
450	            "test.bsky.social",
