452	        )
453	        .expect("build genesis op");
454	
455	        let operation: serde_json::Value =
456	            serde_json::from_str(&genesis_op.signed_op_json).expect("parse op json");
457	
458	        let audit_log = serde_json::json!([{
459	            "did": did,
460	            "cid": "bafy_ac61_genesis",
461	            "createdAt": "2026-03-29T00:00:00Z",
462	            "nullified": false,
463	            "operation": operation
464	        }]);
465	
466	        mock_server.mock(|when, then| {
467	            when.method(GET).path(format!("/{did}/log/audit"));
468	            then.status(200)
469	                .header("content-type", "application/json")
