471	        });
472	
473	        // First call: new entry signed by device key → authorized → no alert
474	        let changes = monitor.check_for_changes(did).await.expect("check failed");
475	        assert_eq!(changes.len(), 0, "Device-key-signed op should not alert");
476	
477	        // Second call: cache updated, no new entries
478	        let changes = monitor.check_for_changes(did).await.expect("check failed");
479	        assert_eq!(changes.len(), 0, "No new changes after cache update");
